    for ax,letter,gene in zip(axs[:3],'ABC',motor):
        q=image_panel(ax,d.fixed(gene),gene);title=gene+' fixed DNA field';panel(ax,letter,title);register(key,letter,title,q,'one fixed field','First date and site0, centered native crop, source-NT intensity limits and65-micrometer bar. The image was not chosen by effect size.','frozen raw DNA fields and mask geometry')
    ax=axs[3];q=d.descriptors[d.descriptors.gene.isin(genes)&(~d.descriptors.metric.eq('scaled_NND')|d.descriptors.model.eq('quadratic_area_AR'))].copy();q['scaled']=q.effect_control_SD;metrics=['log_area','log_AR','solidity','log_density','scaled_NND','global_pair_order','position_axis_coupling','log_DNA_proxy'];v=q.groupby(['gene','metric']).scaled.mean().unstack().reindex(index=genes,columns=metrics);im=ax.imshow(v,vmin=-3,vmax=3,cmap='RdBu_r',aspect='auto');ax.set_yticks(range(4),genes,fontsize=7);ax.set_xticks(range(8),['Area','AR','Solidity','Density','Spacing','Global','Coupling','DNA'],rotation=45,ha='right',fontsize=6.5);fig.colorbar(im,ax=ax,fraction=.035,pad=.02);title='Multiple nuclear-organization descriptors';panel(ax,'D',title);register(key,'D',title,q,'gene means across dates','Effects are divided by their method-specific control residual SD, with colors capped at plus/minus3 for display. Spacing uses quadratic area and AR adjustment. DNA intensity is a proxy, not a cell-cycle assignment.','all descriptor models')
