    ax.axhline(1,color='#555555',lw=.7);ax.axvline(1,color='#555555',lw=.7);ax.set(xlabel='Nuclear count target/source ratio',ylabel='Nuclear area target/source ratio');ax.set_ylim(.93,1.19);ax.legend(frameon=False,fontsize=7.5,ncol=2,loc='upper center',bbox_to_anchor=(.5,-.3));title='All-site count and area context';panel(ax,'F',title);register(key,'F',title,q,'all nine sites in each target and source well across five dates','Ratios use every native site, including those below collective director gates. Zero counts remain in count averages; area ratios are missing if any required site has no valid nucleus. This is raw count/area context, not a proliferation assay or a relaxation of alignment eligibility.','coverage-QC addendum and complete raw covariate tables')
    ax=axs[6];q=pd.read_csv(R/'motor_module_dates.csv');test=d.summary['motor_module']
    if test.get('evaluable',False):
        v=q.value.to_numpy();null=np.asarray(list(itertools.product([-1,1],repeat=5)))@v/5;ax.hist(null,bins=12,color='#CDD6DC',edgecolor='white');ax.axvline(v.mean(),color=COLORS['motor_context'],lw=1.5);ax.text(.98,.97,f"Positive tail {test['positive_tail']:.4f}\nTwo-sided {test['two_sided_tail']:.4f}",transform=ax.transAxes,ha='right',va='top',fontsize=7);source=pd.DataFrame({'sign_assignment_mean':null,'observed_mean':v.mean()})
    else:ax.text(.5,.5,'Complete module unevaluable\nAll missing estimates retained',ha='center',va='center',transform=ax.transAxes);source=q
    ax.set(xlabel='Equal-date motor-context mean',ylabel='Sign assignments');title='Exploratory motor-context summary';panel(ax,'G',title);register(key,'G',title,source,'five complete date means, each averaging three motor genes','All three genes were evaluable on every date. The module mean does not reproduce the positive DYNLL1 alignment shift; this post-discovery comparison remains exploratory.','all32 sign assignments and complete-module rule')
