def fig5(d):
    key='main_figure5';fig,axs=grid();ax=axs[0];q=pd.read_csv(R/'date_repeatability.csv');matrix=np.eye(5)
    for r in q.itertuples():i=DATES.index(r.date_a);j=DATES.index(r.date_b);matrix[i,j]=matrix[j,i]=r.Spearman
    im=ax.imshow(matrix,vmin=-1,vmax=1,cmap='RdBu_r');ax.set_xticks(range(5),[f'R{i+1}' for i in range(5)]);ax.set_yticks(range(5),[f'R{i+1}' for i in range(5)])
    for i,j in itertools.product(range(5),range(5)):ax.text(j,i,f'{matrix[i,j]:.2f}',ha='center',va='center',fontsize=7,color='white' if abs(matrix[i,j])>.6 else 'black')
    title='Cross-date phenotype repeatability';panel(ax,'A',title);register(key,'A',title,q,'complete genes across pairs of acquisition dates','Spearman correlations describe repeatability in this selected panel with shared guide pools; they are not a strict prediction ceiling.','complete-five-date spatial gene effects')
    ax=axs[1];d.gene_scatter(ax,'mean','SD');ax.set(xlabel='Gene mean alignment contrast',ylabel='Between-date SD');title='Mean effects and date variability';panel(ax,'B',title);register(key,'B',title,d.genes,'gene-level means and date SDs','The spread uses dates rather than nuclei as the repeated unit. Shared source and reference wells induce dependencies.','primary gene/date contrasts')
    ax=axs[2];q=d.pred.copy();names=['full_ridge','shape_count_ridge','without_neighbor_orientation_ridge','full_RBF'];labels=['Full ridge','Shape/\ncount','No neighbor/\norientation','Full RBF']
    for i,group in enumerate(['gene','batch']):b=q[q.grouping.eq(group)].set_index('model').reindex(names);ax.plot(range(4),b.R2,'o-',ms=4,lw=.7,color=COLORS['anchor'] if i==0 else '#788690',label='Gene held out' if i==0 else 'Date held out');ax.axhline(b.training_mean_R2.iloc[0],color=COLORS['anchor'] if i==0 else '#788690',ls='--',lw=.65,alpha=.6,label='Gene baseline' if i==0 else 'Date baseline')
    zero(ax);ax.set_xticks(range(4),labels,fontsize=7.5);ax.set_ylabel('Out-of-fold R²');ax.legend(frameon=False,fontsize=7.5,ncol=2,loc='upper center',bbox_to_anchor=(.5,-.31),handlelength=1.3,columnspacing=.8);title='Linear and nonlinear profile prediction';panel(ax,'C',title);register(key,'C',title,q,'evaluable gene/date observations under grouped validation','Dashed lines show the outer-training-mean baselines. Poor prediction is not proof of genome-wide irreducibility.','nested prediction summaries')
    for ax,letter,model,title in [(axs[3],'D','full_ridge','Complete-profile linear predictions'),(axs[4],'E','full_RBF','Complete-profile nonlinear predictions')]:
        q=d.oof[d.oof.model.eq(model)&d.oof.grouping.eq('gene')];diagonal(ax,q.effect,q.predicted);ax.scatter(q.effect,q.predicted,s=7,alpha=.25,color='#7B8A94',rasterized=True);b=q[q.gene.eq('DYNLL1')];ax.scatter(b.effect,b.predicted,s=28,color=COLORS['anchor'],label='DYNLL1');ax.set(xlabel='Observed alignment contrast',ylabel='Gene-held-out prediction');ax.legend(frameon=False,fontsize=6.8);panel(ax,letter,title);register(key,letter,title,q,'gene/date out-of-fold predictions','Training-fold preprocessing and hyperparameter selection exclude the held-out gene. Source-profile preprocessing and image controls remain shared.','all out-of-fold predictions')
    ax=axs[5];q=d.oof[d.oof.model.eq('full_ridge')&d.oof.grouping.eq('gene')].copy();q['model_error']=(q.effect-q.predicted).abs();q['baseline_error']=(q.effect-q.training_mean).abs();v=q.groupby('gene',as_index=False)[['model_error','baseline_error']].mean();v['improvement']=v.baseline_error-v.model_error;v=v.sort_values('improvement');ax.scatter(range(len(v)),v.improvement,s=13,color='#7B8A94');b=v.reset_index(drop=True);idx=np.flatnonzero(b.gene.eq('DYNLL1'))
    if len(idx):ax.scatter(idx,b.loc[idx,'improvement'],s=35,color=COLORS['anchor'])
    zero(ax);ax.set(xlabel='Genes ordered by error improvement',ylabel='MAE baseline minus model');title='Prediction gains and failures across genes';panel(ax,'F',title);register(key,'F',title,v,'held-out genes','Every gene contributes its mean absolute error difference from its outer-training-mean baseline. Favorable and unfavorable model results are retained.','full ridge out-of-fold errors')
    ax=axs[6];q=pd.read_csv(R/'all_definition_gene_summary.csv');primary=q[q.model.eq('adaptive_conditional')][['gene','mean']].rename(columns={'mean':'primary'})
    for i,model in enumerate(['adaptive_unconditional','fixed_conditional','fixed_unconditional']):b=q[q.model.eq(model)].merge(primary,on='gene');ax.scatter(b.primary,b['mean'],s=12,alpha=.5,color=['#529D7E','#9467A8','#C56B36'][i],label=model.replace('_',' '))
    combined=q[q.model.isin(['adaptive_unconditional','fixed_conditional','fixed_unconditional'])].merge(primary,on='gene');diagonal(ax,combined.primary,combined['mean']);ax.set(xlabel='Primary gene mean',ylabel='Alternative-definition gene mean');ax.legend(frameon=False,fontsize=5.8);title='Radius and null-definition sensitivity';panel(ax,'G',title);register(key,'G',title,combined,'gene means under fixed endpoint definitions','Definitions share images and gene reagents; their differences are estimator sensitivities rather than independent validation.','all four frozen alignment definitions')
    ax=axs[7];q=pd.read_csv(R/'leave_one_date_out_comparator_sensitivity.csv');ax.plot(range(5),q.difference,'o-',color=COLORS['anchor'],ms=4);zero(ax);ax.set_xticks(range(5),[f'R{i+1}' for i in range(5)]);ax.set(xlabel='Omitted date',ylabel='DYNLL1 minus matched median');title='Dependence on individual acquisition dates';panel(ax,'H',title);register(key,'H',title,q,'five leave-one-date-out diagnostics','The fixed complete comparator set and full-control model calibration are retained. Date averaging and comparator summaries are recomputed after each omission. This is sensitivity analysis rather than an independently refitted validation.','prespecified matched comparators and primary effects');group_legend(fig,'Gene groups in B');finish(fig,key)

def main_figures(d):
    for function in [fig1,fig2,fig3,fig4,fig5]:function(d)
